using System.IO;
using System.Text;
using System.Text.RegularExpressions;

namespace Inferpal.Services.Tools;

/// <summary>
/// Files a tool or a designer writes, which an edit by hand breaks or loses: what makes one generated, and where the
/// change belongs instead.
/// </summary>
/// <remarks>
/// <para>
/// ⚠ A property of the FILE, not a list of names: an <c>&lt;auto-generated&gt;</c> header (the marker every generator
/// writes — XAML and Razor <c>*.g.cs</c>, <c>Resources.Designer.cs</c>, EF Core migration metadata and model snapshots,
/// gRPC and other code generators), or the Windows Forms designer's region in a <c>*.Designer.cs</c>. An edit by hand
/// compiles and runs, then the generator writes over it, or the designer can no longer open the form.
/// </para>
/// <para>
/// ⚠ The marker counts only in the file's LEADING comment block (before its first line of code): a test, an analyzer or
/// a source generator that writes the marker in a string or a later comment is no generated file, and refusing it
/// would lock the agent out of ordinary code. The designer region is looked for in the whole text of a
/// <c>*.Designer.cs</c>, which is small.
/// </para>
/// </remarks>
internal static class GeneratedFiles
{
    /// <summary>Why a file is generated, and where its change belongs.</summary>
    /// <param name="What">What wrote it, for the model: "an <c>&lt;auto-generated&gt;</c> file", "the Windows Forms designer's code".</param>
    /// <param name="Source">The file it is generated from, when it can be named; <c>null</c> otherwise.</param>
    /// <param name="Remedy">Where the change goes instead, as a sentence for the model.</param>
    /// <param name="Designer">The Windows Forms designer's file: a change there can be the only fix (a handler that no
    /// longer exists), so the person decides on the card — warned — instead of a refusal.</param>
    internal sealed record Generated(string What, string? Source, string Remedy, bool Designer = false);

    /// <summary>How much of a file's head carries the marker.</summary>
    private const int HeadChars = 4096;

    private static readonly Regex AutoGenerated = new(@"<\s*auto-generated\b", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant, RegexBudget.Default);
    private static readonly Regex ProtoSource = new(@"^\s*//\s*source:\s*(?<p>\S+\.proto)\s*$", RegexOptions.Multiline | RegexOptions.CultureInvariant, RegexBudget.Default);
    private static readonly Regex DesignerRegion = new(@"#region\s+(?:Windows Form|Component) Designer generated code", RegexOptions.CultureInvariant, RegexBudget.Default);

    /// <summary>File-name suffixes of generated files, with the extension of the source beside them (empty: the stem is
    /// the source).</summary>
    private static readonly (string Suffix, string SourceExt)[] Generators =
        [(".g.i.cs", ""), (".g.cs", ""), (".Designer.cs", ".resx"), (".Designer.cs", ".settings")];

    /// <summary>The file at <paramref name="path"/> as generated, or <c>null</c>; an unreadable file is not generated
    /// (the tool that reads it says why it cannot).</summary>
    public static Generated? Of(string path)
    {
        try
        {
            if (!File.Exists(path)) return null;
            return Of(path, TextFileEncoding.ReadText(path));
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            Diagnostics.Swallow("GeneratedFiles.Of", ex);
            return null;
        }
    }

    /// <inheritdoc cref="Of(string)"/>
    public static Generated? Of(string path, string text)
    {
        var name = Path.GetFileName(path);
        var head = LeadingComments(text.Length <= HeadChars ? text : text[..HeadChars]);
        var dir = Path.GetDirectoryName(path) ?? string.Empty;

        if (name.EndsWith(".Designer.cs", StringComparison.OrdinalIgnoreCase) && !AutoGenerated.IsMatch(head)
            && DesignerRegion.IsMatch(text))
        {
            var form = name[..^".Designer.cs".Length] + ".cs";
            return new Generated("the Windows Forms designer's code (InitializeComponent)", null,
                $"change the form in the designer, or put the code in {form}, which the designer does not rewrite",
                Designer: true);
        }
        if (!AutoGenerated.IsMatch(head)) return null;
        // A migration's own Up/Down file is written by hand, even under a copied header: its metadata — the
        // [Migration] attribute — lives in the .Designer.cs beside it.
        if (Regex.IsMatch(text, @":\s*Migration\b", RegexOptions.CultureInvariant, RegexBudget.Default)
            && !text.Contains("[Migration(", StringComparison.Ordinal))
            return null;

        if (ProtoSource.Match(head) is { Success: true } proto)
            return new Generated("generated by the protocol buffer compiler", proto.Groups["p"].Value,
                $"change {proto.Groups["p"].Value}; the code is generated from it again");
        if (text.Contains("[Migration(", StringComparison.Ordinal) || Regex.IsMatch(text, @":\s*ModelSnapshot\b", RegexOptions.CultureInvariant, RegexBudget.Default))
            return new Generated("Entity Framework Core migration metadata", null,
                "change the model (the entity classes or the DbContext), then add a migration (dotnet ef migrations add <Name>); "
                + "a migration's own Up/Down file, the one without .Designer, is the one written by hand");
        foreach (var (suffix, sourceExt) in Generators)
        {
            if (!name.EndsWith(suffix, StringComparison.OrdinalIgnoreCase)) continue;
            var stem = name[..^suffix.Length];
            var source = sourceExt.Length == 0 ? stem : stem + sourceExt;
            if (sourceExt.Length > 0 && !File.Exists(Path.Combine(dir, source))) continue;
            // obj/…/MainWindow.g.cs, Pages/Index.razor.g.cs: the stem names the markup it is compiled from — when that
            // markup exists in the project; a source generator's output has none (its source is the code it reads).
            if (sourceExt.Length == 0)
            {
                var candidates = Path.GetExtension(stem).Length > 0 ? [stem] : new[] { stem + ".xaml", stem + ".axaml" };
                if (ProjectFolder(path) is not { } project
                    || candidates.FirstOrDefault(c => FindsFile(project, c)) is not { } markup)
                    return new Generated("generated by the build", null,
                        "it is written again at every build: change what it is generated from — the markup, or the code a "
                        + "source generator reads (its attributes)");
                source = markup;
            }
            return new Generated("generated by the build", source, $"change {source}; this file is generated from it again");
        }
        return new Generated("marked <auto-generated>", null,
            "the tool that wrote it writes it again: change what it is generated from");
    }

    /// <summary>The comment lines a file starts with (blank lines, <c>#pragma</c> and <c>#nullable</c> included), up to
    /// its first line of code.</summary>
    private static string LeadingComments(string head)
    {
        var sb = new StringBuilder();
        var inBlock = false;
        foreach (var raw in head.Split('\n'))
        {
            var line = raw.Trim();
            if (inBlock)
            {
                sb.Append(line).Append('\n');
                if (line.Contains("*/", StringComparison.Ordinal)) inBlock = false;
                continue;
            }
            if (line.Length == 0 || line.StartsWith("//", StringComparison.Ordinal) || line.StartsWith("#pragma", StringComparison.Ordinal)
                || line.StartsWith("#nullable", StringComparison.Ordinal) || line.StartsWith('\'') || line.StartsWith("<!--", StringComparison.Ordinal))
            {
                sb.Append(line).Append('\n');
                continue;
            }
            if (line.StartsWith("/*", StringComparison.Ordinal))
            {
                sb.Append(line).Append('\n');
                inBlock = !line.Contains("*/", StringComparison.Ordinal);
                continue;
            }
            break;
        }
        return sb.ToString();
    }

    /// <summary>The project folder a build output sits in: the parent of its <c>obj</c> folder; <c>null</c> outside one.</summary>
    private static string? ProjectFolder(string path)
    {
        for (var dir = Path.GetDirectoryName(path); !string.IsNullOrEmpty(dir); dir = Path.GetDirectoryName(dir))
            if (Path.GetFileName(dir).Equals("obj", StringComparison.OrdinalIgnoreCase))
                return Path.GetDirectoryName(dir);
        return Path.GetDirectoryName(path);
    }

    private static bool FindsFile(string folder, string name)
    {
        try { return WorkspaceScan.EnumerateFiles(folder, name).Any(); }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException) { return false; }
    }

    /// <summary>What a tool that edits a file by hand answers for a generated one; <c>null</c> for an ordinary file and
    /// for the designer's, which goes to the card with <see cref="DesignerWarning"/>.</summary>
    public static string? EditRefusal(string path) =>
        Of(path) is { Designer: false } g
            ? $"'{path}' is {g.What}: an edit by hand is written over when it is generated again. Nothing was written — {g.Remedy}."
            : null;

    /// <summary>The warning the card carries for an edit of the Windows Forms designer's file, in the person's language;
    /// <c>null</c> for any other file. The card is then forced: no rule, no "always" approves it.</summary>
    public static string? DesignerWarning(string path) =>
        Of(path) is { Designer: true } ? Localization.Strings.DesignerFileWarning(Path.GetFileName(path)) : null;
}
